"""Byte-for-byte comparison with prompts generated by the TypeScript reference.

Goldens live in tests/golden/prompts/<case>.{json,txt}; regenerate them with
tools/golden/generate.mts (see its header).
"""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from genui.library import Library
from genui.prompt import system_prompt

ROOT = Path(__file__).resolve().parent.parent
CASES = sorted((ROOT / "tests/golden/prompts").glob("*.json"))

OPTION_NAMES = {
    "toolCalls": "tool_calls",
    "bindings": "bindings",
    "builtinFunctions": "builtin_functions",
    "editMode": "edit_mode",
    "inlineMode": "inline_mode",
    "tools": "tools",
    "preamble": "preamble",
    "examples": "examples",
    "toolExamples": "tool_examples",
    "additionalRules": "additional_rules",
}


def _load(case: Path) -> tuple[Path, dict, str]:
    data = json.loads(case.read_text(encoding="utf-8"))
    opts = {OPTION_NAMES[k]: v for k, v in data.get("options", {}).items()}
    expected = case.with_suffix(".txt").read_text(encoding="utf-8")
    return ROOT / data["library"], opts, expected


def test_golden_cases_exist():
    assert len(CASES) >= 20
    for case in CASES:
        assert case.with_suffix(".txt").exists(), case.name


@pytest.mark.parametrize("case", CASES, ids=[c.stem for c in CASES])
def test_matches_reference(case: Path):
    lib_path, opts, expected = _load(case)
    lib = Library.from_spec(lib_path, validate=False)  # groups.json has an unknown group member on purpose
    assert system_prompt(lib, **opts) == expected
    assert lib.system_prompt(**opts) == expected


@pytest.mark.parametrize("case", CASES[:3], ids=[c.stem for c in CASES[:3]])
def test_accepts_dict_json_and_path(case: Path):
    lib_path, opts, expected = _load(case)
    text = lib_path.read_text(encoding="utf-8")
    assert system_prompt(json.loads(text), **opts) == expected
    assert system_prompt(text, **opts) == expected
    assert system_prompt(str(lib_path), **opts) == expected


def test_deterministic():
    lib = Library.from_spec(ROOT / "spec/fixtures/1.0/library.json")
    assert lib.system_prompt(tools=["x"]) == lib.system_prompt(tools=["x"])


def test_builtin_functions_false_overrides_tool_calls():
    lib = Library.from_spec(ROOT / "spec/fixtures/1.0/library.json")
    on = lib.system_prompt(tool_calls=True)
    off = lib.system_prompt(tool_calls=True, builtin_functions=False)
    assert "@Count(array: any[])" in on
    assert "@Count(array: any[])" not in off
    # custom functions still get their own section
    assert "## Built-in Functions\n\n@Upper(text: string) → string" in off


def test_empty_tools_list_does_not_enable_tool_calls():
    lib = Library.from_spec(ROOT / "spec/fixtures/1.0/library.json")
    assert "## Query" not in lib.system_prompt(tools=[])
